     1→/**
     2→ * FreeLang Nexus - AST 노드 정의
     3→ * V 모드 함수와 Python 모드 함수 통합 AST
     4→ */
     5→
     6→/**
     7→ * 모든 AST 노드의 기본 인터페이스
     8→ */
     9→export interface ASTNode {
    10→  type: string;
    11→  line: number;
    12→  column: number;
    13→  mode: 'v' | 'python' | 'auto';
    14→}
    15→
    16→/**
    17→ * 파라미터 정의
    18→ */
    19→export interface Parameter {
    20→  name: string;
    21→  typeAnnotation?: string; // i64, string 등 (선택)
    22→  line: number;
    23→  column: number;
    24→}
    25→
    26→/**
    27→ * V 모드 함수
    28→ * 예: fn add(x: i64, y: i64) -> i64 { return x + y }
    29→ */
    30→export interface VFunction extends ASTNode {
    31→  type: 'VFunction';
    32→  name: string;
    33→  params: Parameter[];
    34→  returnType?: string; // -> 타입
    35→  body: Statement[];
    36→  mode: 'v';
    37→}
    38→
    39→/**
    40→ * Python 모드 함수
    41→ * 예: def add(a, b): return a + b
    42→ */
    43→export interface PyFunction extends ASTNode {
    44→  type: 'PyFunction';
    45→  name: string;
    46→  params: Parameter[];
    47→  returnType?: string; // -> 타입 (선택)
    48→  body: Statement[];
    49→  mode: 'python';
    50→}
    51→
    52→/**
    53→ * Return 문장
    54→ */
    55→export interface ReturnStatement extends ASTNode {
    56→  type: 'Return';
    57→  value?: Expression;
    58→}
    59→
    60→/**
    61→ * 할당 문장
    62→ */
    63→export interface AssignStatement extends ASTNode {
    64→  type: 'Assign';
    65→  name: string;
    66→  typeAnnotation?: string; // let x: i64[] = ... 형식 타입 힌트
    67→  value: Expression;
    68→}
    69→
    70→/**
    71→ * 표현식 문장
    72→ */
    73→export interface ExprStatement extends ASTNode {
    74→  type: 'ExprStatement';
    75→  expression: Expression;
    76→}
    77→
    78→/**
    79→ * If 문장
    80→ */
    81→export interface IfStatement extends ASTNode {
    82→  type: 'IfStatement';
    83→  condition: Expression;
    84→  thenBranch: Statement[];
    85→  elseBranch?: Statement[];
    86→}
    87→
    88→/**
    89→ * While 루프
    90→ */
    91→export interface WhileStatement extends ASTNode {
    92→  type: 'WhileStatement';
    93→  condition: Expression;
    94→  body: Statement[];
    95→}
    96→
    97→/**
    98→ * Break 문장
    99→ */
   100→export interface BreakStatement extends ASTNode {
   101→  type: 'Break';
   102→}
   103→
   104→/**
   105→ * Continue 문장
   106→ */
   107→export interface ContinueStatement extends ASTNode {
   108→  type: 'Continue';
   109→}
   110→
   111→/**
   112→ * For-In 루프
   113→ * for i in range(10) { body }
   114→ * for item in arr { body }
   115→ */
   116→export interface ForStatement extends ASTNode {
   117→  type: 'ForStatement';
   118→  variable: string;     // 루프 변수명
   119→  iterable: Expression; // range(10) CallExpr 또는 arr Identifier
   120→  body: Statement[];
   121→}
   122→
   123→/**
   124→ * 문장 타입
   125→ */
   126→export type Statement = ReturnStatement | AssignStatement | ExprStatement | IfStatement | WhileStatement | ForStatement | BreakStatement | ContinueStatement;
   127→
   128→/**
   129→ * 숫자 리터럴
   130→ */
   131→export interface NumberLiteral extends ASTNode {
   132→  type: 'Number';
   133→  value: number | string; // 16진수, 이진수 표현 가능
   134→}
   135→
   136→/**
   137→ * 문자열 리터럴
   138→ */
   139→export interface StringLiteral extends ASTNode {
   140→  type: 'String';
   141→  value: string;
   142→}
   143→
   144→/**
   145→ * 식별자 (변수명, 함수명 등)
   146→ */
   147→export interface Identifier extends ASTNode {
   148→  type: 'Identifier';
   149→  name: string;
   150→}
   151→
   152→/**
   153→ * 이항 연산식
   154→ * 예: x + y, a * b
   155→ */
   156→export interface BinaryExpr extends ASTNode {
   157→  type: 'BinaryExpr';
   158→  left: Expression;
   159→  operator: string; // +, -, *, /, &&, ||, ==, !=, <, >, <=, >=
   160→  right: Expression;
   161→}
   162→
   163→/**
   164→ * 함수 호출 표현식
   165→ * 예: foo(), Module::func()
   166→ */
   167→export interface CallExpr extends ASTNode {
   168→  type: 'Call';
   169→  callee: Expression | string; // Identifier 또는 Module::func 형식 문자열
   170→  args: Expression[];
   171→}
   172→
   173→/**
   174→ * 배열 리터럴
   175→ * 예: [1, 2, 3], []
   176→ */
   177→export interface ArrayLiteral extends ASTNode {
   178→  type: 'Array';
   179→  elements: Expression[];
   180→}
   181→
   182→/**
   183→ * 배열 접근
   184→ * 예: arr[0], items[i]
   185→ */
   186→export interface ArrayAccess extends ASTNode {
   187→  type: 'ArrayAccess';
   188→  object: Expression;
   189→  index: Expression;
   190→}
   191→
   192→/**
   193→ * 멤버 접근
   194→ * 예: arr.length, obj.property
   195→ */
   196→export interface MemberAccess extends ASTNode {
   197→  type: 'MemberAccess';
   198→  object: Expression;
   199→  property: string;
   200→}
   201→
   202→/**
   203→ * 구조체 필드 정의
   204→ */
   205→export interface StructField {
   206→  name: string;
   207→  typeAnnotation: string;
   208→  line: number;
   209→  column: number;
   210→}
   211→
   212→/**
   213→ * 구조체 정의
   214→ * 예: struct Person { name: string, age: i64 }
   215→ */
   216→export interface StructDef extends ASTNode {
   217→  type: 'StructDef';
   218→  name: string;
   219→  fields: StructField[];
   220→  mode: 'v';
   221→}
   222→
   223→/**
   224→ * 구조체 리터럴
   225→ * 예: Person { name: "Alice", age: 30 }
   226→ */
   227→export interface StructLiteral extends ASTNode {
   228→  type: 'StructLiteral';
   229→  name: string;
   230→  fields: { [key: string]: Expression };
   231→}
   232→
   233→/**
   234→ * 표현식 타입
   235→ */
   236→export type Expression = NumberLiteral | StringLiteral | Identifier | BinaryExpr | CallExpr | ArrayLiteral | ArrayAccess | MemberAccess | StructLiteral;
   237→
   238→/**
   239→ * @call 지시문 - 외부 언어 라이브러리 호출 (버스 터미널)
   240→ * @call python:numpy 1.24
   241→ * @call rust:rand 0.8
   242→ * @call go:github.com/gin-gonic/gin
   243→ */
   244→export interface ExternCall extends ASTNode {
   245→  type: 'ExternCall';
   246→  lang: 'python' | 'rust' | 'go' | 'julia' | 'js' | 'c' | 'cpp';
   247→  package: string;   // 패키지명 (numpy, rand, github.com/... 등)
   248→  version?: string;  // 선택적 버전 (1.24, 0.8 등)
   249→  alias?: string;    // as alias (선택)
   250→}
   251→
   252→/**
   253→ * 프로그램 (최상위 노드)
   254→ */
   255→export interface Program {
   256→  type: 'Program';
   257→  body: Array<VFunction | PyFunction | StructDef | Statement | ExternCall>;
   258→}
