   577→          } else if (value.type === 'Array') {
   578→            const arrLit = value as AST.ArrayLiteral;
   579→            const firstElem = arrLit.elements[0] as any;
   580→            let elemType = 'long long';
   581→            if (firstElem?.type === 'String') elemType = 'char*';
   582→            else if (firstElem?.type === 'Number' && String(firstElem.value).includes('.')) elemType = 'double';
   583→            const len = arrLit.elements.length;
   584→            this.writeC(`${this.indent()}${elemType} ${varName}[${len}] = ${expr};`);
